/**
 * Converts degrees to radians.
 *
 * @author Jonathan Olson <jonathan.olson@colorado.edu>
 */
import '../../../globals.js';
import dot from '../dot.js';
export function toRadians(degrees) {
    return Math.PI * degrees / 180;
}
dot.register('toRadians', toRadians);
